"""Small math helpers."""


def clamp(value, low, high):
    """Return value limited to the inclusive range low..high.

    Raises ValueError if low > high.
    """
    if low > high:
        raise ValueError(f"low ({low}) must not be greater than high ({high})")
    return max(low, min(value, high))

import pytest

from mathx import clamp


def test_value_inside_range_is_unchanged():
    assert clamp(5, 0, 10) == 5


def test_value_below_low_returns_low():
    assert clamp(-3, 0, 10) == 0


def test_value_above_high_returns_high():
    assert clamp(42, 0, 10) == 10


def test_boundaries_and_equal_bounds():
    assert clamp(0, 0, 10) == 0
    assert clamp(10, 0, 10) == 10
    assert clamp(7, 3, 3) == 3


def test_low_greater_than_high_raises():
    with pytest.raises(ValueError):
        clamp(5, 10, 0)

