def wrap(value, low, high):
    """Return value wrapped modularly into the half-open range [low, high).

    Raises ValueError if low >= high. Unlike clamp, low == high is rejected
    because a zero-width range has nothing to wrap into.
    """
    if low >= high:
        raise ValueError(f"low ({low}) must be less than high ({high})")
    return low + (value - low) % (high - low)
